// spec: specs/catalog.md §14 · кейс .qa/tests/catalog/cat-25-photo-capture-save.md
// seed: tests/seed.admin.spec.ts
// catalog · #6afef6 (b1d20da96d1dd96bd56afef6, הושלם; ручная QA 18.10, backfill 25.10) — окно «תמונות המוצר» из ячейки «תמונה»:
//   «צילום» только фиксирует кадр — без выбора файла (filechooser) и без сохранения; вместо кнопки — «צילום חוזר» / «שמירה»;
//   только «שמירה» сохраняет фото к товару, оно сразу видно в строке каталога; окно прижато к верху, «צילום» не смещается после сохранения.
// Камера — fake-устройство Chromium (только проект desktop «tests»; WebKit fake-камеру не умеет). Реальная камера iPad/Safari — только вручную.
// Данные: свой товар «QA-AUTO-catalog-<ts>» (без места и остатка), фото fake-камеры — только на него; afterAll удаляет товар.
// @data — создаёт/удаляет товар в общем каталоге.
import { test, expect, Page } from '@playwright/test';
import * as H from '../inventory/_places';

test.use({
  storageState: H.ADMIN,
  permissions: ['camera'],
  launchOptions: { args: ['--use-fake-ui-for-media-stream', '--use-fake-device-for-media-stream'] },
});
test.describe.configure({ mode: 'serial' });

const TS = Date.now().toString().slice(-7);
const P = `QA-AUTO-catalog-${TS}`;
const created = new Set<string>();

const HINT_LIVE = 'כוונו את המצלמה לאריזת המוצר ולחצו «צילום».';
const HINT_SHOT = 'בדקו את התמונה ולחצו «שמירה» כדי להוסיף אותה למוצר.';
const addBtn = (page: Page) => page.getByRole('button', { name: `הוספת תמונה למוצר — ${P}`, exact: true });
const imagesBtn = (page: Page) => page.getByRole('button', { name: `תמונות המוצר — ${P}`, exact: true });

async function openDialog(page: Page, hasImage: boolean) {
  await H.findProduct(page, P);
  await (hasImage ? imagesBtn(page) : addBtn(page)).click();
  const dlg = page.getByRole('dialog');
  await expect(dlg.getByRole('heading', { name: 'תמונות המוצר' })).toBeVisible();
  await expect(dlg.getByText(P)).toBeVisible();
  const shot = dlg.getByRole('button', { name: 'צילום', exact: true });
  await expect(shot).toBeEnabled({ timeout: 20_000 }); // камера готова
  await expect(dlg.getByText(HINT_LIVE, { exact: true })).toBeVisible();
  return { dlg, shot };
}

test.describe('catalog — «צילום» בחלון «תמונות המוצר»: צילום בלי בחירת קובץ, שמירה רק ב«שמירה» (#6afef6)', () => {
  test.afterAll(async ({ browser }) => {
    test.setTimeout(120_000);
    await H.cleanup(browser, created, new Map());
  });

  test('«צילום» מקפיא את הפריים בלי חלון בחירת קובץ ובלי שמירה; «צילום חוזר»/«שמירה»; רק «שמירה» מוסיפה תמונה שנראית בקטלוג; «צילום» לא זז #6afef6 @desktop @data', async ({ page }) => {
    test.setTimeout(180_000);
    await H.createProduct(page, P, `QACAT${TS}`, created);

    let choosers = 0;
    page.on('filechooser', () => { choosers++; });
    let uploads = 0;
    page.on('request', (r) => {
      if (['POST', 'PUT'].includes(r.method()) && /\/storage\/v1\/object\//.test(r.url())) uploads++;
    });

    // 1. окно: прижато к верху, «צילום» доступна
    let { dlg, shot } = await openDialog(page, false);
    const dlgBox = (await dlg.boundingBox())!;
    expect(dlgBox.y, 'окно прижато к верху экрана').toBeLessThan(60);
    const before = (await shot.boundingBox())!;

    // 2. «צילום» → кадр заморожен: вместо «צילום» — «צילום חוזר» и «שמירה», подсказка про «שמירה»
    await shot.click();
    const retake = dlg.getByRole('button', { name: 'צילום חוזר' });
    const save = dlg.getByRole('button', { name: 'שמירה', exact: true });
    await expect(retake).toBeVisible();
    await expect(save).toBeVisible();
    await expect(shot).toHaveCount(0);
    await expect(dlg.getByText(HINT_SHOT, { exact: true })).toBeVisible();
    expect(choosers, '«צילום» не открывает выбор файла').toBe(0);
    expect(uploads, 'до «שמירה» ничего не загружено').toBe(0);
    await expect(dlg.getByText('ראשי', { exact: true })).toHaveCount(0);

    // 3. «צילום חוזר» → снова живая камера; второй «צילום» — тоже без выбора файла
    await retake.click();
    await expect(shot).toBeEnabled({ timeout: 20_000 });
    await expect(dlg.getByText(HINT_LIVE, { exact: true })).toBeVisible();
    await shot.click();
    await expect(save).toBeVisible();
    expect(choosers, 'второй «צילום» не открывает выбор файла').toBe(0);

    // 4. закрыть без «שמירה» → фото у товара нет
    await dlg.getByRole('button', { name: 'סגירה', exact: true }).click();
    await expect(page.getByRole('dialog')).toHaveCount(0);
    expect(uploads, 'закрытие без «שמירה» ничего не сохраняет').toBe(0);
    await H.findProduct(page, P);
    await expect(addBtn(page)).toBeVisible();
    await expect(imagesBtn(page)).toHaveCount(0);

    // 5. снова: «צילום» → «שמירה» → миниатюра «ראשי», «צילום» вернулась на то же место
    ({ dlg, shot } = await openDialog(page, false));
    const start = (await shot.boundingBox())!;
    expect(Math.abs(start.y - before.y), 'позиция «צילום» при повторном открытии').toBeLessThanOrEqual(1);
    await shot.click();
    await dlg.getByRole('button', { name: 'שמירה', exact: true }).click();
    await expect(dlg.getByText('ראשי', { exact: true })).toHaveCount(1, { timeout: 20_000 });
    expect(uploads, '«שמירה» загрузила фото в storage').toBeGreaterThan(0);
    await expect(shot).toBeEnabled({ timeout: 20_000 });
    const after = (await shot.boundingBox())!;
    expect(Math.abs(after.y - start.y), '«צילום» не сместилась после сохранения').toBeLessThanOrEqual(1);
    expect(Math.abs(after.x - start.x)).toBeLessThanOrEqual(1);
    expect(choosers).toBe(0);

    // 6. закрыть → в строке каталога фото этого товара; после обновления — остаётся
    await dlg.getByRole('button', { name: 'סגירה', exact: true }).click();
    await expect(page.getByRole('dialog')).toHaveCount(0);
    await expect(imagesBtn(page)).toBeVisible({ timeout: 20_000 });
    await expect(H.row(page, P).locator('img').first()).toBeVisible();
    await H.findProduct(page, P);
    await expect(imagesBtn(page)).toBeVisible();
    await expect(H.row(page, P).locator('img').first()).toBeVisible();
    await expect(addBtn(page)).toHaveCount(0);
  });
});
